+                    @Target(ElementType.TYPE_USE)
+                    @interface Ann2 {}
+                    @interface Ann3 {}
+                    private void test() {
+                        java.lang.@Ann1 System.out.println("");
+                        java.lang.@Ann1 @Ann2 System.out.println("");
+                        java.lang.System.@Ann3 out.println("");
+                    }
+                }
+                """);
+
